use super::*;
use std::collections::BTreeMap;
pub(crate) struct Fixture {pub base:super::presentation_tests::Fixture,pub name:String,pub original:Lock,pub indirect:Lock}
pub(crate) fn fixture(advanced:bool)->Fixture {let base=super::presentation_tests::fixture(advanced,advanced);let name="sample-imported-scene".to_owned();let p=Project::open_for_install(&base.root,Runtime::content_only().engine_version).unwrap();let original=p.verify().unwrap();let dependencies=BTreeMap::from([(name.clone(),original.packages[&name].manifest.version.clone())]);let parent=base.temp.path().join("keep parent source");fs::create_dir(&parent).unwrap();fs::write(parent.join("orr.package.json"),serde_json::to_vec(&serde_json::json!({"schema":1,"name":"keep-parent","version":"1.0.0","engine":"^0.0.1","capabilities":[],"dependencies":dependencies,"files":["LICENSE.txt"]})).unwrap()).unwrap();fs::write(parent.join("LICENSE.txt"),"User fixture license").unwrap();p.install(&[parent.clone()]).unwrap();let indirect=p.remove(&name).unwrap();fs::rename(&parent,parent.with_extension("hidden")).unwrap();Fixture {base,name,original,indirect}}
pub(crate) fn files(root:&Path)->BTreeMap<PathBuf,Vec<u8>> {fn walk(root:&Path,p:&Path,out:&mut BTreeMap<PathBuf,Vec<u8>>) {for e in fs::read_dir(p).unwrap() {let e=e.unwrap();let path=e.path();if e.file_type().unwrap().is_dir() {walk(root,&path,out);}else{out.insert(path.strip_prefix(root).unwrap().to_path_buf(),fs::read(path).unwrap());}}}let mut out=BTreeMap::new();walk(root,root,&mut out);out}
#[test]
fn keep_plan_preserves_saved_models_and_parent_removal_keeps_game_valid() {let f=fixture(false);let before=files(&f.base.root);let initial=open_room_project(&f.base.root).unwrap().scene().frame().to_bytes();let plan=plan_keep(&f.base.root,&f.name).unwrap();assert_eq!(files(&f.base.root),before);assert_eq!(plan.preview().previous,f.indirect);assert_eq!(plan.preview().candidate.packages,f.indirect.packages);let kept=apply_keep(&plan).unwrap();assert!(kept.direct.contains_key(&f.name));let removed=apply_remove(&plan_remove(&f.base.root,"keep-parent").unwrap()).unwrap();assert_eq!(removed,f.original);assert_eq!(open_room_project(&f.base.root).unwrap().scene().frame().to_bytes(),initial);let mut after=files(&f.base.root);after.insert(PathBuf::from("orr.packages.lock.json"),before[Path::new("orr.packages.lock.json")].clone());assert_eq!(after,before);}
#[test]
fn stale_saved_bytes_lock_and_foreign_writer_cannot_publish_keep() {
    let f=fixture(false);let plan=plan_keep(&f.base.root,&f.name).unwrap();let path=f.base.root.join("room.camera.json");let mut doc:serde_json::Value=serde_json::from_slice(&fs::read(&path).unwrap()).unwrap();doc["yaw"]=serde_json::json!(0.5);fs::write(&path,serde_json::to_vec_pretty(&doc).unwrap()).unwrap();open_room_project(&f.base.root).unwrap();let before=files(&f.base.root);assert!(apply_keep(&plan).is_err());assert_eq!(files(&f.base.root),before);
    let f=fixture(false);let plan=plan_keep(&f.base.root,&f.name).unwrap();let p=Project::open(&f.base.root,room_runtime()).unwrap();let now=p.remove_checked("keep-parent",&f.indirect,&p.preview_remove("keep-parent").unwrap().candidate,||Ok(())).unwrap();let before=files(&f.base.root);assert!(apply_keep(&plan).is_err());assert_eq!(p.verify().unwrap(),now);assert_eq!(files(&f.base.root),before);
    let f=fixture(false);let plan=plan_keep(&f.base.root,&f.name).unwrap();let guard=f.base.root.join(".orr/packages/writer.lock");fs::write(&guard,"foreign writer").unwrap();let before=files(&f.base.root);assert!(apply_keep(&plan).is_err());assert_eq!(files(&f.base.root),before);
}
#[test]
fn keep_profile_admission_uses_only_editor_owned_consent() {let f=fixture(true);let before=files(&f.base.root);assert_eq!(plan_keep(&f.base.root,&f.name).is_ok(),cfg!(all(feature="room-character",feature="room-lighting")));assert_eq!(files(&f.base.root),before);}
#[cfg(all(feature="room-character",feature="room-lighting"))]
#[test]
fn valid_lighting_and_character_edits_reject_old_keep_plan() {for field in ["lighting","character"] {let f=fixture(true);let plan=plan_keep(&f.base.root,&f.name).unwrap();let path=f.base.root.join(format!("room.{field}.json"));let mut doc:serde_json::Value=serde_json::from_slice(&fs::read(&path).unwrap()).unwrap();if field=="lighting" {doc["point_light"]["intensity"]=serde_json::json!(4.0);}else{doc["schema"]=serde_json::json!(2);doc["speeds"]=serde_json::json!({"searching":"2x","carrying":"1x","escaped":"1x"});}fs::write(path,serde_json::to_vec_pretty(&doc).unwrap()).unwrap();open_room_project(&f.base.root).unwrap();let before=files(&f.base.root);assert!(apply_keep(&plan).is_err());assert_eq!(inspect(&f.base.root).unwrap(),f.indirect);assert_eq!(files(&f.base.root),before);}}
